('4255a27b-9e95-5a28-945f-44ec96441151','6d246a80-83cc-4531-8c5e-b32949fc1089','Welcome to academic year 2026-27','Classes for all programmes commence on 15 June 2026. Collect your ID cards from the office.',null,'49e290a4-e1a2-513d-b422-50cc7594e6b0',null,null,null,null,'{}'::uuid[],null,'2026-06-12 09:00:00+05:30'),
('cd947463-aef1-55c5-bfc5-f4728f87af05','6d246a80-83cc-4531-8c5e-b32949fc1089','Mid-semester test timetable published','Mid-semester tests will be held from 21 September. Check the Exams page for subject-wise dates.',array['student','parent']::text[],'1ab72173-5c1f-55bf-beda-41aefe37becb',null,null,null,null,'{}'::uuid[],null,'2026-09-10 10:07:00+05:30'),
('764e4f36-cedf-5110-ab37-54adb6749982','6d246a80-83cc-4531-8c5e-b32949fc1089','Semester end examination schedule','University semester end examinations begin on 7 December 2026. Hall tickets will be issued from the examination section.',array['student','parent']::text[],'1ab72173-5c1f-55bf-beda-41aefe37becb',null,null,null,null,'{}'::uuid[],null,'2026-11-03 11:14:00+05:30'),
